#!/usr/bin/env bash
# One-time PACE (Phoenix) readiness checks for swarmguard, beyond the repo's own checks.
# Run from the repo root on a login node or an Open OnDemand shell, passing your values in the
# environment (do NOT edit this file on PACE: it is in MANIFEST.json, and any change makes safety
# pass 1 fail for every run):
#   ACCOUNT=gts-<pi> GT_EMAIL=<you>@gatech.edu bash PACE-Checks.sh
# Nothing here starts a model. Step 6 uses one 5-minute GPU job
# and step 8 sends test emails; every other step is read-only or a dry run.
# Checks keep going after a failure (no `set -e`): read the output top to bottom.

ACCOUNT="${ACCOUNT:-gts-CHANGEME}"     # your charge account, from `pace-quota`
QOS="${QOS:-inferno}"                 # or "embers" (free but preemptible)
GT_EMAIL="${GT_EMAIL:-CHANGEME@gatech.edu}"   # where Slurm should send mail
SWARM_SIF="${SWARM_SIF:-$HOME/scratch/swarmguard/swarm.sif}"
SWARM_WEIGHTS="${SWARM_WEIGHTS:-$HOME/scratch/swarmguard/weights}"
SWARM_RUNS="${SWARM_RUNS:-$HOME/scratch/swarmguard/runs}"

if [[ "$ACCOUNT" == *CHANGEME* || "$GT_EMAIL" == *CHANGEME* ]]; then
    echo "Usage: ACCOUNT=gts-<pi> GT_EMAIL=<you>@gatech.edu bash PACE-Checks.sh   (account from: pace-quota)"
    exit 1
fi
cd "$(dirname "$0")" || exit 1
step() { printf '\n=== %s\n' "$*"; }

step "1. Charge accounts and QOS limits"
pace-quota
sacctmgr -nP show assoc user="$USER" format=account,qos
sacctmgr -nP show qos "$QOS" format=name,maxwall,maxtrespu,maxjobspu   # 2 h jobs must be allowed

step "2. GPU names and request syntax (dry runs: nothing is submitted)"
sinfo -o "%P %G %f" | grep -i gpu
sbatch --test-only -A "$ACCOUNT" -q "$QOS" slurm/run_single.sbatch
sbatch --test-only -A "$ACCOUNT" -q "$QOS" --gres=gpu:A100:2 slurm/run_single.sbatch   # judge
sbatch --test-only -A "$ACCOUNT" -q "$QOS" slurm/analyze.sbatch                          # CPU report job

step "3. Storage (the governor stops a run when the runs filesystem is < 10% free)"
mkdir -p "$SWARM_RUNS"
df -h "$SWARM_RUNS" "$(dirname "$SWARM_SIF")" "$SWARM_WEIGHTS" 2>/dev/null

step "4. Weights downloaded (pinned revisions: see configs/models.yaml)"
for d in meta-llama/Llama-3.2-3B-Instruct google/gemma-3-27b-it; do
    if [[ -f "$SWARM_WEIGHTS/$d/config.json" ]]; then echo "ok       $d"; else echo "MISSING  $d"; fi
done

step "5. Secret-like environment variables (safety pass 1 refuses them; unset before swarm commands)"
env | cut -d= -f1 | grep -E 'KEY|TOKEN|SECRET|PASSWORD' || echo "none"

step "6. Apptainer, network isolation and GPU inside the container (one 5-minute GPU job)"
if [[ -f "$SWARM_SIF" ]]; then
    srun -A "$ACCOUNT" -q "$QOS" --gres=gpu:A100:1 -c 2 --mem=8G -t 00:05:00 bash -c '
        command -v apptainer >/dev/null || module load apptainer 2>/dev/null
        echo "node: $(hostname)  apptainer: $(apptainer --version 2>&1)"
        # common.sh uses --net --network none; if this is refused, runs cannot start
        apptainer exec --containall --cleanenv --no-home --net --network none "$0" python -c "
import socket
try:
    socket.create_connection((\"1.1.1.1\", 443), timeout=3); print(\"NETWORK: REACHABLE (isolation FAILED)\")
except OSError as e:
    print(\"NETWORK: blocked inside container (good):\", type(e).__name__)
" || echo "NETWORK NAMESPACE: REFUSED (ask PACE / decide with your PI; do not drop the flag)"
        apptainer exec --nv --containall --cleanenv --no-home "$0" nvidia-smi \
            --query-gpu=name,memory.total --format=csv || echo "GPU: NOT VISIBLE in container"
    ' "$SWARM_SIF"
else
    echo "SKIPPED: no container at $SWARM_SIF (build it: apptainer build swarm.sif container/swarm.def)"
fi

step "7. Python for the report venv (needs >= 3.11)"
python3 --version
module avail python 2>&1 | grep -i python | head -5

step "8. Outbound internet from a compute node (only needed for OpenRouter)"
srun -A "$ACCOUNT" -q "$QOS" -N1 -n1 -c1 --mem=1G -t 00:05:00 bash -c '
    echo "node: $(hostname)"
    getent hosts openrouter.ai || echo "DNS: FAILED"
    curl -sS -o /dev/null --max-time 10 -w "HTTPS: %{http_code} in %{time_total}s\n" \
        https://openrouter.ai/api/v1/models || echo "HTTPS: NO OUTBOUND"'

step "9. Slurm email: expect BEGIN + END, then one FAILED"
cat > ~/mailtest.sbatch <<'EOF'
#!/bin/bash
#SBATCH --job-name=mailtest
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=1
#SBATCH --mem=512M
#SBATCH --time=00:05:00
#SBATCH --output=%x-%j.out
echo "job ${SLURM_JOB_ID} on $(hostname) at $(date)"
sleep 60
echo "done at $(date)"
EOF
sbatch -A "$ACCOUNT" -q "$QOS" -o "$HOME/%x-%j.out" --mail-type=BEGIN,END,FAIL --mail-user="$GT_EMAIL" ~/mailtest.sbatch
sbatch -A "$ACCOUNT" -q "$QOS" -t 00:02:00 --mem=256M -J mailfail -o "$HOME/%x-%j.out" \
    --mail-type=FAIL --mail-user="$GT_EMAIL" --wrap="exit 1"
squeue -u "$USER"

step "Done. For the real jobs, export these in your shell (sbatch/salloc read them):"
echo "export SBATCH_ACCOUNT=$ACCOUNT SBATCH_QOS=$QOS SALLOC_ACCOUNT=$ACCOUNT SALLOC_QOS=$QOS"
echo "export SWARM_REPO=$PWD SWARM_SIF=$SWARM_SIF SWARM_WEIGHTS=$SWARM_WEIGHTS SWARM_RUNS=$SWARM_RUNS"
